import jax.numpy as jnp
import optax
import sys
import flax.linen as nn

sys.path.append('storage/episteme')
from dmf_v1 import SharedNeuronMLP, GatingNetwork

BASE_SEED = 42

def _define_hyperparameters():
    return {
        'learning_rate': 1e-3,
        'num_experts': 32,
        'gating_hidden_dim': 32,
        'expert_hidden_size': 64,
    }

# Fixed version of DynamicModularForecaster with axis_size specified
class DynamicModularForecaster(nn.Module):
    num_experts: int
    gating_hidden_dim: int
    expert_hidden_size: int

    @nn.compact
    def __call__(self, x, training=False):
        B, T, N = x.shape
        k = self.num_experts

        # 1. Gating network determines expert weights for each neuron
        gating_weights = GatingNetwork(
            num_experts=k, hidden_dim=self.gating_hidden_dim
        )(x) # Shape: (B, N, k)

        # 2. Vmap a single MLP definition to create k independent experts
        VmappedMLP = nn.vmap(
            SharedNeuronMLP,
            in_axes=None, out_axes=0, # Each expert gets the same input x
            variable_axes={'params': 0, 'batch_stats': 0},
            split_rngs={'params': True, 'dropout': True},
            axis_size=k)  # FIX: Specify axis_size

        # Initialize and apply the k experts. Each expert sees the full input x.
        # The output will have a new leading dimension for the experts.
        expert_outputs = VmappedMLP(
            name="VmappedExperts",
            hidden_size=self.expert_hidden_size,
        )(x, training=training) # Shape: (k, B, 32, N)

        # 3. Combine expert outputs using gating weights
        # Reshape weights for broadcasting: (B, N, k) -> (k, B, 1, N)
        gating_weights_bc = jnp.transpose(gating_weights, (2, 0, 1))[:, :, None, :]

        # Weighted sum: multiply expert outputs by their weights and sum along the expert axis
        y_final = jnp.sum(expert_outputs * gating_weights_bc, axis=0)

        return y_final

class DMF_Wrapper:
    def __init__(self, hparams):
        # Extract only model parameters (exclude learning_rate)
        model_params = {
            'num_experts': hparams['num_experts'],
            'gating_hidden_dim': hparams['gating_hidden_dim'],
            'expert_hidden_size': hparams['expert_hidden_size'],
        }
        self.model = DynamicModularForecaster(**model_params)
        self.needs_rng = True
        self.mutable = ['batch_stats']

    def init(self, rng_key, dummy_input):
        return self.model.init({'params': rng_key, 'dropout': rng_key}, dummy_input, training=True)

    def apply(self, params, x, training=False, mutable=None, rngs=None):
        if mutable:
            output, updates = self.model.apply(params, x, training=training, mutable=mutable, rngs=rngs or {})
            return output, updates
        return self.model.apply(params, x, training=training, rngs=rngs or {})

def create_network(hparams):
    return DMF_Wrapper(hparams)

def compute_loss(p, t, pa, x):
    return jnp.mean(jnp.abs(p - t))

def create_optimizer(lr):
    return optax.adam(learning_rate=lr)
